-- Data dictionary for the advances schema.
--
-- These comments are read by SchemaSpy (published to GitHub Pages) and by anything else that reads
-- pg_description, including the CSV export for the MOJ Data Catalogue / Glue. Keep them updated when
-- columns are added or their meaning changes - SchemaCommentsTest fails the build if a table or column
-- has no comment.
--
-- Every column comment ends with a sensitivity classification:
--
--   [Sensitivity: NONE]                - not personal data in itself (keys, timestamps, process flags,
--                                        and the reference data in the constant_* tables)
--   [Sensitivity: PERSONAL]            - personal data about a prisoner: identifies or locates them
--   [Sensitivity: STAFF]               - personal data about a member of staff, typically the username
--                                        that performed an action
--   [Sensitivity: SPECIAL-CATEGORY]    - UK GDPR Article 9 data (health, sexuality, religion, race,
--                                        gender reassignment) or criminal offence data under Article 10
--   [Sensitivity: OFFICIAL-SENSITIVE]  - not personal data, but damaging if disclosed
--
-- STAFF is still personal data and still in scope for a staff member's own subject access request. It is
-- separated from PERSONAL so that an extract about prisoners can be reasoned about without staff columns
-- inflating the count, and so staff data can be dropped or pseudonymised independently.
--
-- Four things to understand before using these classifications:
--
--   1. They describe the column's own content, not the row's. This schema describes a record about a
--      financial advance of money provided to a prisoner, not people, so almost everything
--      here is about a financial action. This is exactly why the handful of columns that can identify
--      an individual, be combined to place that individual at a location or be combined to identify
--      an amount of money an individual may or has received, matter.
--
--   3. **Every free-text column should be assumed to contain more than its question asks.** A field
--      asking for a description of the hold may contain details of an incident as a reason for the
--      holding of money which may be used to record which prisoner or staff member was involved. Free
--      text is classified on what people actually write in it, not on the field label.
--

------------------------------------------------------------------------------------------------
-- advance_records - the record describing an advance itself
------------------------------------------------------------------------------------------------

COMMENT ON TABLE advance_records IS 'A record of a financial advance of money provided to a prisoner by a prison.';

COMMENT ON COLUMN advance_records.id IS 'Primary key. A UUIDv7 generated by the application, used as the advances''s permanent public identifier across DPS. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.legacy_payment_profile_id IS 'NOMIS payment profile number, allowing these records to be linked back to the original source record held in NOMIS. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.legacy_information_number IS 'NOMIS advance information number, allowing these records to be linked back to the original source record held in NOMIS. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.prison_number IS 'NOMIS offender number (prison number/noms number) of the prisoner that the money has been advanced to. The link that makes every row here personal data about that prisoner. Updated in place when NOMIS merges two offender records. [Sensitivity: PERSONAL]';
COMMENT ON COLUMN advance_records.prison_id IS 'Prison code, such as MDI, where the money advanced to the prisoner was from. Read with prison_number it indicates where that prisoner was held at the time. [Sensitivity: PERSONAL]';
COMMENT ON COLUMN advance_records.amount IS 'The amount of money that is/was advanced to the prisoner. [Sensitivity: OFFICIAL-SENSITIVE]';
COMMENT ON COLUMN advance_records.repayment_start_date IS 'When the repayments did/will start to be taken from the prisoner. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.repayment_amount IS 'The amount of money that will be attempted to be taken as a repayment towards the advance of monies to the prisoner. [Sensitivity: OFFICIAL-SENSITIVE]';
COMMENT ON COLUMN advance_records.reference IS 'Free text reference value about the advance. Free text: assume it can name an incident, prisoner, staff member or member of the public, for example when accidentally used instead of the comment explaining why the money has been advanced or who has approved the advance. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.created_on IS 'When this advance record was first created, indicating when the prisoner received the advance of money which combined with the amount could implicate the prisoner as a target for coercion. [Sensitivity: OFFICIAL-SENSITIVE]';
COMMENT ON COLUMN advance_records.created_by IS 'DPS username of the person who recorded the advance to the prisoner from the prison. [Sensitivity: STAFF]';
COMMENT ON COLUMN advance_records.updated_at IS 'When this advance record was last updated. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.status IS 'The current status of this advance - ACTIVE, REPAID, WRITTEN_OFF. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_records.comment IS 'Free text description about the advance. Free text: assume it can name an incident, prisoner, staff member or member of the public, for example when explaining why the money has been advanced or who has approved the advance. [Sensitivity: OFFICIAL-SENSITIVE]';

------------------------------------------------------------------------------------------------
-- advance_record_payments - the record describing a payment of an advance or a repayment towards an advance
------------------------------------------------------------------------------------------------

COMMENT ON TABLE advance_record_payments IS 'A record of a financial payment of some money as a result of or towards an advance of monies to a prisoner by a prison.';

COMMENT ON COLUMN advance_record_payments.id IS 'Primary key. A UUIDv7 generated by the application, used as the advance payment''s permanent public identifier across DPS. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_record_payments.advance_record_id IS 'Foreign Key. A UUIDv7 referencing the advance_record this advance payment is associated with. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_record_payments.transaction_id IS 'The unique identifier of the prisoner finance general ledger transaction that issued the advance monies or helped repay the money advanced, allowing these records to be linked back to the financial records held within the general ledger of accounts. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_record_payments.posting_type IS 'What kind of payment to the prisoner this is - CR = CREDIT or DR = DEBIT. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_record_payments.amount IS 'The amount of money that is/was advanced to the prisoner or repaid by the prisoner. [Sensitivity: OFFICIAL-SENSITIVE]';
COMMENT ON COLUMN advance_record_payments.timestamp IS 'When this advance repayment record was first created. [Sensitivity: NONE]';
COMMENT ON COLUMN advance_record_payments.created_by IS 'DPS username of the person who recorded the advance to the prisoner from the prison or the repayment from the prisoner. [Sensitivity: STAFF]';
